window.ScripturaLexicons.BDAG_PART_0242 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-01\" data-source=\"BDAG\" data-search=\"Ναγγαί, ὁ nome próprio masculino Nagai BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναγγαί, ὁ</td><td>nome próprio masculino</td><td>Nagai</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-02\" data-source=\"BDAG\" data-search=\"Ναζαρά, ἡ nome próprio feminino Nazaré BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναζαρά, ἡ</td><td>nome próprio feminino</td><td>Nazaré</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-03\" data-source=\"BDAG\" data-search=\"Ναζαρηνός, ή, όν adjetivo; substantivo masculino nazareno; de Nazaré BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναζαρηνός, ή, όν</td><td>adjetivo; substantivo masculino</td><td>nazareno; de Nazaré</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-04\" data-source=\"BDAG\" data-search=\"Ναζωραῖος, ου, ὁ substantivo masculino nazoreu; nazareno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναζωραῖος, ου, ὁ</td><td>substantivo masculino</td><td>nazoreu; nazareno</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-05\" data-source=\"BDAG\" data-search=\"Ναθάμ, ὁ nome próprio masculino Natã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναθάμ, ὁ</td><td>nome próprio masculino</td><td>Natã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-06\" data-source=\"BDAG\" data-search=\"Ναθαναήλ, ὁ nome próprio masculino Natanael BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναθαναήλ, ὁ</td><td>nome próprio masculino</td><td>Natanael</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-07\" data-source=\"BDAG\" data-search=\"ναί partícula sim; certamente; de fato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ναί</td><td>partícula</td><td>sim; certamente; de fato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-08\" data-source=\"BDAG\" data-search=\"Ναιμάν, ὁ nome próprio masculino Naamã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναιμάν, ὁ</td><td>nome próprio masculino</td><td>Naamã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-09\" data-source=\"BDAG\" data-search=\"Ναί̈ν, ἡ nome próprio feminino Naim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναί̈ν, ἡ</td><td>nome próprio feminino</td><td>Naim</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-10\" data-source=\"BDAG\" data-search=\"ναός, οῦ, ὁ substantivo masculino templo; santuário; corpo ou comunidade como templo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ναός, οῦ, ὁ</td><td>substantivo masculino</td><td>templo; santuário; corpo ou comunidade como templo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-11\" data-source=\"BDAG\" data-search=\"Ναούμ, ὁ nome próprio masculino Naum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναούμ, ὁ</td><td>nome próprio masculino</td><td>Naum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-12\" data-source=\"BDAG\" data-search=\"ναοφόρος, ον adjetivo; substantivo portador de templo ou santuário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ναοφόρος, ον</td><td>adjetivo; substantivo</td><td>portador de templo ou santuário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-13\" data-source=\"BDAG\" data-search=\"νάρδος, ου, ἡ substantivo feminino nardo; óleo de nardo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νάρδος, ου, ἡ</td><td>substantivo feminino</td><td>nardo; óleo de nardo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-14\" data-source=\"BDAG\" data-search=\"νάρκη, ης, ἡ substantivo feminino torpor; dormência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νάρκη, ης, ἡ</td><td>substantivo feminino</td><td>torpor; dormência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-15\" data-source=\"BDAG\" data-search=\"Νάρκισσος, ου, ὁ nome próprio masculino Narciso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νάρκισσος, ου, ὁ</td><td>nome próprio masculino</td><td>Narciso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-16\" data-source=\"BDAG\" data-search=\"ναυαγέω verbo sofrer naufrágio; arruinar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ναυαγέω</td><td>verbo</td><td>sofrer naufrágio; arruinar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-17\" data-source=\"BDAG\" data-search=\"Ναυή, ὁ nome próprio masculino Num, pai de Josué BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναυή, ὁ</td><td>nome próprio masculino</td><td>Num, pai de Josué</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-18\" data-source=\"BDAG\" data-search=\"ναύκληρος, ου, ὁ substantivo masculino proprietário de navio; capitão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ναύκληρος, ου, ὁ</td><td>substantivo masculino</td><td>proprietário de navio; capitão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-19\" data-source=\"BDAG\" data-search=\"ναῦς, ἡ substantivo feminino navio, embarcação maior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ναῦς, ἡ</td><td>substantivo feminino</td><td>navio, embarcação maior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0242-20\" data-source=\"BDAG\" data-search=\"ναύτης, ου, ὁ substantivo masculino marinheiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ναύτης, ου, ὁ</td><td>substantivo masculino</td><td>marinheiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0242-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναγγαί, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναγγαί</span>, <span class=\"greek\">ὁ</span>, indeclinável, Nagai, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:25</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναζαρά, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναζαρά</span>, <span class=\"greek\">ἡ</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:16</a>), <span class=\"greek\">Ναζαρέτ</span>, <span class=\"greek\">Ναζαρέθ</span>; nas variantes de leitura, também <span class=\"greek\">Ναζαράτ</span>, <span class=\"greek\">Ναζαράθ</span>, indeclinável, Nazaré. Também como plural neutro AcPl BMM verso 38f [<span class=\"greek\">ἐν</span> <span class=\"greek\">Να</span>]<span class=\"greek\">ζαροῖς</span>//AcPl Ha 8, 30 [<span class=\"greek\">ἐν</span> <span class=\"greek\">Ν</span>]<span class=\"greek\">αζαρά</span>. Sobre as formas variantes do nome, ver JZenner, ZKT 18, 1894, 744–47; Dalman, Gramm.2 152; FBurkitt, The Syriac Forms of NT Proper Names 1912, 16; 28f, JTS 14, 1913, 475f; Zahn sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>; B-D-F §39, 2; W-S. §5, 27e e p. xvi sobre §5 nota 58; Mlt-H. 107f. <span class=\"greek\">Ναζαρέτ</span> (também Just., D. 78, 4) e <span class=\"greek\">Ναζαρέθ</span> parecem possuir o melhor testemunho.—Cidade natal dos pais de Jesus; o lugar não é mencionado no AT, no Talmude, no Midraxe nem em Joseph., mas desempenha papel importante na tradição cristã: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>; 4:13; 21:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:26</a>; 2:4, 39, 51; 4:16 (BViolet, Z. recht. Verst. der Naz.-Perikope Lk 4:16–30: ZNW 37, ’39, 251–71); J 1:45f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:38</a>; AcPl Ha 8, 30//BMM verso 38f.—Sobre N., ver HGuthe, RE XIII 1903, 676ff, Palästina2 1927, 149ff; Dalman, Orte3 61–88; GSchumacher, D. jetzige Naz.: ZDPV 13, 1890, 235ff; PViaud, Naz. et ses deux églises 1910; MBrückner, Naz. die Heimat Jesu: PJ 7, 1911, 74–84; TSoiron, D. Ev. u. die. hl. Stätten 1929, 17–37; PWinter, ‘Naz.’ and ‘Jerus.’ in Lk 1 and 2, NTS 3, ’56/57, 136–42; CKopp, The Holy Places of the Gospels, trad. RWalls, ’63, 49–86.—MAvi-Yonah, The Caesarea Inscription of the Twenty-Four Priestly Courses: The Teacher’s Yoke, ed. JVardaman e outros, ’64, 46–57, especialmente p. 48 nota 2. BHHW III 1291f; Kl. Pauly IV 27.—OEANE IV 113f. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναζαρηνός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναζαρηνός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span>, proveniente de Nazaré; empregado somente como substantivo <span class=\"greek\">ὁ</span> <span class=\"greek\">Ν</span>., o Nazareno, habitante de Nazaré, aplicado apenas a Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:24</a>; 10:47 (variantes de leitura <span class=\"greek\">Ναζωρηνός</span> e <span class=\"greek\">Ναζωραῖος</span>); 14:67; 16:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:34</a>; 24:19 (variante de leitura <span class=\"greek\">Ναζωραῖος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:5</a> D. JBecker, Jesus of Nazareth, ’98—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναζωραῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναζωραῖος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, nazoreu, nazareno, designação predominantemente de Jesus, em Mt, J, Ac e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:37</a>, ao passo que Mk tem <span class=\"greek\">Ναζαρηνός</span> (ver esse verbete). Dos dois lugares nos quais esta última forma aparece em Lk, um, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:34</a>, aparentemente deriva de Mk (1:24); o outro, 24:19, talvez de uma fonte especial. Quando o autor de Lk-Ac escreve sem influência de outra fonte, emprega <span class=\"greek\">Ναζωραῖος</span>. Mt declara expressamente em 2:23 que Jesus foi assim chamado porque cresceu em Nazaré. Além disso, os outros autores do NT que chamam Jesus de <span class=\"greek\">Ναζωραῖος</span> conhecem Nazaré como sua terra natal. Linguisticamente, porém, a passagem de <span class=\"greek\">Ναζαρέτ</span> a <span class=\"greek\">Ναζωραῖος</span> é difícil (Dalman, Gramm.2 178; Wlh. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.69\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:69</a>; MLidzbarski, Mandäische Liturgien 1920, xviff, Zeitschrift für Semitistik 1, 1922, 230ff, Ginza 1925, ixf; FBurkitt, The Syriac Forms of NT Proper Names 1912; AvGall, <span class=\"greek\">Βασιλεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 1926 p. 432, 4; cf. 411f; RBultmann, ZNW 24, 1925, 143f, Jesus 1926, 26 [trad. inglesa 24]; HSchaeder em Rtzst. u. Schaeder, Studien zum antiken Synkretismus 1926 p. 308, 2, também TW IV 879–84; Moore adiante), e é preciso ter em mente que <span class=\"greek\">Ναζωραῖος</span> significava algo diferente antes de ser associado a Nazaré (cf. Orig. Celsus 7, 18, 9f, que chama Jesus <span class=\"greek\">ὁ</span> <span class=\"greek\">Ναζωραῖος</span> <span class=\"greek\">ἄνθρωπος</span>. JSanders, JBL 84, ’65, 169–72 [revisto em: The Gospels and the Scriptures of Israel, ed. CEvans/WStegner ’94, 116–28], interpreta <span class=\"greek\">Ν</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a> como significando tanto “proveniente de Nazaré” quanto “nascido milagrosamente”). As passagens nas quais Jesus recebe esse nome são <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>; 26:69, variante de leitura, 71; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:5</a>, 7; 19:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:22</a>; 3:6; 4:10; 6:14; 22:8; 26:9. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:5</a>, os cristãos eram assim chamados; ver Kl. Texte 32 p. 3, ln. 32 e 83 p. 6, linhas 8, 17, 27; p. 7, nota sobre ln. 1ff; p. 8, ln. 5; p. 9, ln.17; 23; p. 10, ln. 5; 15; p. 11, ln. 28 e nota sobre ln. 9ff, todas passagens em que cristãos judeus são chamados Nazaraei, Nazareni, <span class=\"greek\">Ναζωραῖοι</span>.—Laud. Therap. 27, os monges são chamados <span class=\"greek\">ναζιραῖοι</span> (com a variante de leitura <span class=\"greek\">Ναζαραῖοι</span>).—EbNestle, ET 19, 1908, 523f, PM 14, 1910, 349f; HZimmern, ZDMG 74, 1920, 429ff; GMoore, Nazarene and Nazareth: Beginn. I/1, 1920, 426–32 (ver I/5, ’33, 356f); EMeyer II 408f; 423, 2; HGressmann, ZKG 41=n.s. 4, 1922, 166f; WCaspari, ZNW 21, 1922, 122–27; HSmith, <span class=\"greek\">Ναζωραῖος</span> <span class=\"greek\">κληθήσεται</span>: JTS 28, 1927, 60; ELohmeyer, Joh. d. Täufer ’32, p. 115, 2; HSchlier, TRu n.s. 5, ’33, 7f; WOesterley, ET 52, ’41, 410–12; SLyonnet, Biblica 25, ’44, 196–206; MBlack, An Aramaic Approach3, ’67, 197–200; WAlbright, JBL 65, ’46, 397–401, também JKennard, Jr., ibid. 66, ’47, 79–81; HShires, ATR 29, ’47, 19–27; TNicklin, Gospel Gleanings, ’50, 257–60; BGärtner, Die rätselhafte Termini Nazoräer u. Iskariot ’57, 5–36; ESchweizer, Judentum, Urchrist., Kirche ’60, 90–93; RPesch: The Gospels and the Scriptures of Israel ’94, 178–211.—B-D-F §39, 4; BHHW II, 1293. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναθάμ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναθάμ</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">נָתָן</span>), Natã, filho de Davi (2 Km 5:14; Zech 12:12 <span class=\"greek\">Ναθάν</span>, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:31</a>, variante de leitura; Just., D. 118, 2.—Em Jos., Ant. 7, 70 <span class=\"greek\">Νάθας</span> [acusativo -<span class=\"greek\">αν</span>]); na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:31</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναθαναήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναθαναήλ</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">נְתַנְאֵל</span>. Cf. Num 1:8; 2 Esdr [Ezra] 10:22; 1 Ch 2:14; 15:24.—Em Jos., Ant. 6, 161; 20, 14 <span class=\"greek\">Ναθαναῆλος</span>, <span class=\"greek\">ου</span>), Natanael, discípulo de Jesus, mencionado somente em J (1:45–49; 21:2). Não aparece nas listas sinóticas dos doze apóstolos; por isso, desde a Antiguidade, procura-se identificá-lo com vários apóstolos, especialmente Bartolomeu, bem como com outras personalidades; alguns abandonaram a tentativa de incluí-lo entre os doze. Ver Hdb.3, excursus sobre J 1, final. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:2</a>, era de Caná, na Galileia. Ver também o fragmento de evangelho apócrifo do papiro de Berlim 11710: ZNW 22, 1923, 153f, citado em ASyn. 21, 75.—REisler, Das Rätsel des Joh-Ev. ’36, 475–85; JJeremias, D. Berufung des N.: <span class=\"greek\">Αγγελος</span> III, 1928, 2–5; UHolzmeister, Biblica 21, ’40, 28–39; GQuispel, ZNW 47, ’56, 281–83; BHHW II. 1289.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναί</h1><div class=\"entry-meta\"><span>partícula</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ναί</span>, partícula que exprime afirmação, concordância ou ênfase (Hom. e posteriores; POxy 1413, 7 e outros papiros; LXX, TestSol, TestAbr; JosAs17:1 cód. A; ApcSed 3:2; ApcMos 17:1; EpArist 201 <span class=\"greek\">ναί</span>, <span class=\"greek\">βασιλεῦ</span>; Jos., Ant. 17, 169; Just.), sim, certamente, de fato, é verdade que.</p><p class=\"entry-text\">ⓐ Em resposta a uma pergunta:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Feita por outra pessoa: sim (Ael. Aristid. 34 p. 663 D.; Lucian, Dial. Deor. 4, 1 e outros; Alexander Numenianus [época de Adriano]: Rhet. Gr. ed. LSpengel III 1856 p. 24f: a resposta a uma pergunta deve ser <span class=\"greek\">ναὶ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οὔ</span>; Ammonius Phil., In Int. p. 199, 21 <span class=\"greek\">ἀποκρίν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ναὶ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὔ</span>; Sb 7696, 57 [250 d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:28</a>; 13:51; 17:25; 21:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:27</a>; 21:15f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:8</a>; 22:27; GPt 10:42; Hs 9, 11, 8; GJs 19:1, códices; AcPl Ha 5, 2 (restaurado).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Feita por aquele que responde: sim, de fato; <span class=\"greek\">ναὶ</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:26</a> fornece uma resposta afirmativa à pergunta dirigida à multidão, confirmando assim a correção da opinião da multidão; as pessoas estão “no caminho certo”, mas precisam de instrução adicional.—Se a pergunta é formulada negativamente, a resposta pode significar “claro que sim” <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:29</a> (cf. após declaração negativa TestAbr A 17 p. 99, 9 [Stone p. 46]; ApcMos 17).</p><p class=\"entry-text\">ⓑ Em declarações de concordância com afirmações alheias: certamente, sem dúvida, exatamente (Gen 42:21; Epict. 2, 7, 9 <span class=\"greek\">ναί</span>, <span class=\"greek\">κύριε</span>; Diod S 13, 26, 1 <span class=\"greek\">ναί</span>, <span class=\"greek\">ἀλλά</span> = “sim, mas”; Lucian, Jupp. Tr. 6 e 9 <span class=\"greek\">ναί</span>. <span class=\"greek\">ἀλλὰ</span> …) <span class=\"greek\">ναί</span>, <span class=\"greek\">κύριε</span>· <span class=\"greek\">καὶ</span> <span class=\"greek\">γάρ</span>, certamente, Senhor (ou senhor); e contudo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:28</a>, variante de leitura (mas pode significar também repetição insistente do pedido: B-D-F §441, 1; AFridrichsen, ConNeot 1, ’36, 10–13; Athen. Tafel Elderkin 2 [III d.C.]: Hesperia 6, ’37, 383ff, ln. 7, invocação fervorosa numa oração: <span class=\"greek\">ναὶ</span> <span class=\"greek\">κύριε</span> <span class=\"greek\">Τυφώς</span>, <span class=\"greek\">ἐκδίκησον</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">βοήθησον</span> <span class=\"greek\">αὐτῷ</span>; PGM 1, 216 <span class=\"greek\">ναί</span>, <span class=\"greek\">κύριε</span>; cf. 36, 227); Hv 3, 3, 1; 4, 3, 1; m 6, 1, 1. Provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:13</a>; 16:7; 22:20b, variante de leitura, pertencem a este grupo.</p><p class=\"entry-text\">ⓒ Em repetição enfática de uma afirmação própria: sim (de fato) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:21</a>; 11:51. <span class=\"greek\">ναὶ</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ὑμῖν</span>, <span class=\"greek\">τοῦτον</span> <span class=\"greek\">φοβήθητε</span>, sim, de fato, é a este que deveis temer, eu vos digo 12:5.—Phlm 20; 14:1. A repetição pode consistir em ter precedido um pedido e seguir outro semelhante: <span class=\"greek\">ναὶ</span> <span class=\"greek\">ἐρωτῶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σέ</span>, sim, e também te peço <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:3</a>.—1 Cl 60:3.</p><p class=\"entry-text\">ⓓ Em afirmação solene (Herodas 1, 86 <span class=\"greek\">ναὶ</span> <span class=\"greek\">Δήμητρα</span> = “por Deméter”) <span class=\"greek\">ναὶ</span> <span class=\"greek\">ἔρχομαι</span> <span class=\"greek\">ταχύ</span>, certamente venho em breve <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:20</a>. <span class=\"greek\">ναί</span>, <span class=\"greek\">ἀμήν</span>, assim seja, com toda certeza 1:7.</p><p class=\"entry-text\">ⓔ Num jogo de palavras, <span class=\"greek\">ναί</span> é empregado com <span class=\"greek\">οὔ</span>: <span class=\"greek\">ἤτω</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ναὶ</span> <span class=\"greek\">ναί</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὒ</span> <span class=\"greek\">οὔ</span>, seja vosso “sim”, sim, e vosso “não”, não, isto é, a confiabilidade absoluta de vossas declarações deve tornar desnecessário o juramento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>. Mas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:37</a> diz <span class=\"greek\">ἔστω</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ναὶ</span> <span class=\"greek\">ναί</span>, <span class=\"greek\">οὒ</span> <span class=\"greek\">οὔ</span>, isto é, um “sim” claro, um “não” claro e nada mais (<span class=\"greek\">ναί</span> duplicado também em Archilochus [VII a.C.] 99 Diehl3; Alciphron 4, 13, 8; Theodor. Prodr. 8, 321 Hercher; PGM 1, 90; PMinear, NovT 13, ’71, 1–13). Todavia, muitos (B-D-F §432, 1; Wlh., EKlostermann, M‘Neile sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:37</a>; CTorrey, The Four Gospels ’33, 291; ELittmann, ZNW 34, ’35, 23f) admitem que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:37</a> tenha o mesmo significado de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>; o evangelho de Koridethi (manuscrito <span class=\"greek\">Θ</span>) harmoniza o texto da passagem de Mt com o de Js.—Paulo nega que, ao elaborar seus planos, tenha agido de tal maneira <span class=\"greek\">ἵνα</span> <span class=\"greek\">ᾖ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ναὶ</span> <span class=\"greek\">ναὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὒ</span> <span class=\"greek\">οὔ</span>, que meu “sim” fosse ao mesmo tempo “não” <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:17</a>; cf. versículo 18. Isso é tão impossível quanto que, no evangelho, <span class=\"greek\">ναὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὔ</span>, “sim” e “não”, sejam pregados simultaneamente, versículo 19a. Ao contrário, em Jesus Cristo há somente “sim”, versículo 19b, para todas as promessas de Deus, versículo 20.—EKutsch, Eure Rede aber sei ja ja, nein nein: EvTh ’60, 206–18.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναιμάν, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναιμάν</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">נַעֲמָן</span>. Sobre as diferentes grafias tradicionais do nome, ver B-D-F §37; 53, 2; Mlt-H. p. 84), Naamã, comandante do exército sírio, curado da lepra por Eliseu (4 Km 5:1ff; ver BHHW III 1279) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:27</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναί̈ν, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναί̈ν</span>, <span class=\"greek\">ἡ</span>, indeclinável (na Bíblia, somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:11</a>. O nome designa uma localidade idumeia em Jos., Bell. 4, 511, variante de leitura; 517), Naim, cidade da Galileia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:11</a>.—Dalman, PJ 9, 1913, 45; Abel, Geographie II ’38, 394f; CKopp, The Holy Places of the Gospels, trad. RWalls, ’63, 236–41; BHHW II 1283f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ναός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores; ver B-D-F §44, 1; Mlt-H. 71; 121), lugar ou edificação especificamente associado a uma divindade ou reservado para ela, a qual é frequentemente concebida como residente ali: templo.</p><p class=\"entry-text\">ⓐ De templos em geral (Diod S 5, 15, 2 <span class=\"greek\">θεῶν</span> <span class=\"greek\">ναούς</span>; Ar. 3:2; Just., A I, 9, 1; Hippol., Ref. 5, 26, 33) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:24</a>. Especificamente de templos: réplicas do templo de Ártemis em Éfeso 19:24 (Tat. 3:1); mas aqui, próximo de <span class=\"greek\">ἱερόν</span>, versículo 27 (cf. OGI 90, 34 [196 a.C.]; Sb 8745, 6 [papiro de 171/72 d.C.] <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> <span class=\"greek\">Σοκνοβραίσεως</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">ξύλινος</span> <span class=\"greek\">περικεχρυσωμένος</span>. Semelhantemente 8747, 5; 3 Macc 1:10; Philo, Leg. ad Gai. 139 <span class=\"greek\">ἱερὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ναοί</span>, Decal. 7; Jos., Ant. 16, 106), <span class=\"greek\">ναός</span> pode ser entendido no sentido mais restrito de santuário, lugar onde ficava a imagem da deusa (assim em Hdt. e outros; Diod S 1, 97, 9; 20, 14, 3; UPZ 5, 27=6, 22 [163 a.C.], ver nota do editor; BGU 1210, 191 <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">ἱερῷ</span>, <span class=\"greek\">ὅπου</span> <span class=\"greek\">ναός</span> <span class=\"greek\">ἐστιν</span>; 211; PErlang 21 [II d.C.]: APF 14, ’41, 100f, um santuário com um <span class=\"greek\">ξόανον</span> de Ísis).</p><p class=\"entry-text\">ⓑ Do templo de Jerusalém (3 Km 6:5, 17 e outros; Jos., Ant. 8, 62ff; Just., D. 36, 6 e outros; SibOr 3, 575; 657; 702; Stephan. Byz. s.v. <span class=\"greek\">Σόλυμα</span>: <span class=\"greek\">ὁ</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἱεροσολύμοις</span>.—<span class=\"greek\">ναός</span> [<span class=\"greek\">νεώς</span>] do templo de Herodes: Philo, In Flacc. 46, Leg. ad Gai. 278 e outros; Jos., Bell. 5, 185; 207; 215, Ant. 15, 380; Orig., C. Cels. 1, 47, 11; Did., Gen. 135, 17; 192, 23; também de todo o recinto do templo: Jos., Bell. 6, 293, C. Ap. 2, 119) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:17</a>, 35; 27:5, 40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:58</a> (sobre esse dito, ver RHoffmann, Heinrici Festschr. 1914, 130–39 e MGoguel, Congr. d’Hist. du Christ. I 1928, 117–36. De modo mais geral, DPlooij, Jes. and the Temple: ET 42, ’31, 36–39); 15:29; Lk 1:21f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.48\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:48</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:2</a>; 1 Cl 41:2; 16:1ff; GPt 7:26. <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">Ἰσραήλ</span> 16:5; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἱερεῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ναοῦ</span> 7:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">καταπέτασμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span>, o véu do templo que separava o Santo dos Santos do Lugar Santo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:45</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ναοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰερουσαλήμ</span> GPt 5:20. <span class=\"greek\">τὰ</span> <span class=\"greek\">παθνώματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span>, o teto apainelado do templo GJs 24:3. Juramento pelo templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:16</a>, 21. De modo mais completo, <span class=\"greek\">ὁ</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (como em ParJer 4:4; Jos., Ant. 15, 380; cf. Artem. 2, 26 <span class=\"greek\">νεὼς</span> <span class=\"greek\">θεοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:61</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:4</a> (sobre isso, ver WWrede, Die Echtheit des 2 Th 1903, 96ff); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:1</a> (sobre a profecia do salvamento do templo da destruição geral, cf. Jos., Bell. 6, 285). <span class=\"greek\">ὁ</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:9</a>; cf. 1 Cl 23:5 (Mal 3:1). <span class=\"greek\">ναὸς</span> <span class=\"greek\">κυρίου</span> GJs (16 vezes), também <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">αὐτοῦ</span> 23:1.</p><p class=\"entry-text\">ⓒ De santuário celestial (cf. Ps 10:4; 17:7; Wsd 3:14 <span class=\"greek\">ν</span>. <span class=\"greek\">κυρίου</span>; Philo, Spec. Leg. 1, 66; TestLevi 5:1), em Rv: <span class=\"greek\">ὁ</span> <span class=\"greek\">ναός</span> 14:15; 15:6, 8ab; 16:1, 17. <span class=\"greek\">ὁ</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) 7:15; 11:19b. <span class=\"greek\">ὁ</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> 14:17. <span class=\"greek\">ὁ</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> 11:19a. <span class=\"greek\">ὁ</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκηνῆς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μαρτυρίου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> 15:5. Ver também 3:12. Entretanto, não haverá templo na Nova Jerusalém 21:22a; o próprio Deus é o santuário da cidade eterna, versículo 22b.</p><p class=\"entry-text\">ⓓ Do corpo humano ou de parte dele, em linguagem figurada (Philo, Op. M. 136f sobre o <span class=\"greek\">σῶμα</span> como <span class=\"greek\">νεὼς</span> <span class=\"greek\">ἱερὸς</span> <span class=\"greek\">ψυχῆς</span>; Tat. 15, 2).—Do corpo dos cristãos cheios do Espírito, considerado habitação de Deus e, portanto, templo (Iren. 5, 9, 4 [PJena]; Hippol., Ref. 5, 19, 15; cf. Sextus 35), o qual não deve ser contaminado pela indulgência pecaminosa (sobre os regulamentos greco-romanos de pureza para a entrada em templos, ver, por exemplo, SIG 983 e nota 3): <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">πνεύματός</span> <span class=\"greek\">ἐστιν</span>, vosso corpo é templo do Espírito Santo (que habita) em vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:19</a>. A habitação do coração é <span class=\"greek\">ν</span>. <span class=\"greek\">ἅγιος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> 6:15; cf. o desenvolvimento desse pensamento em 16:6–10 (dito pitagórico em HSchenkl, Wiener Stud 8, 1886, 273 n.º 66 <span class=\"greek\">νεὼς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σοφὸς</span> <span class=\"greek\">νοῦς</span>, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">χρὴ</span> <span class=\"greek\">παρασκευάζειν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κατακοσμεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">παραδοχὴν</span> <span class=\"greek\">θεοῦ</span>. Cf. Sextus 46a; Synes., Dio 9 p. 49c <span class=\"greek\">νεὼς</span> <span class=\"greek\">οὗτος</span> [isto é, o <span class=\"greek\">νοῦς</span> <span class=\"greek\">οἰκεῖος</span> <span class=\"greek\">θεῷ</span> = o <span class=\"greek\">Νοῦς</span> é o verdadeiro templo de Deus]). De cristãos cheios do Espírito <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τέλειον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> 4:11. <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">θεοῦ</span> 2 Cl 9:3; <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">θεοῦ</span> IPhld 7:2. Por isso, os cristãos individualmente são chamados <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">θεοῦ</span>) <span class=\"greek\">ναοί</span> IEph 15:3. De uma congregação cristã <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:16</a>, 17ab; 2 Cor 6:16ab. <span class=\"greek\">αὔξει</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:21</a>. Os cristãos são <span class=\"greek\">λίθοι</span> <span class=\"greek\">ναοῦ</span> <span class=\"greek\">πατρός</span>, pedras para o templo do Pai IEph 9:1. Para enfatizar fortemente a unidade da comunidade cristã (que não admite divisão), os cristãos recebem esta exortação: <span class=\"greek\">πάντες</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">συντρέχετε</span> <span class=\"greek\">θεοῦ</span>, reuni-vos todos como num único templo de Deus IMg 7:2.—(Cf. <span class=\"greek\">ναοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">κόσμου</span>, “o mundo inteiro é o templo de Deus” Orig., C. Cels. 7, 44, 38).—Ver <span class=\"greek\">ἱερόν</span> b.—KBaltzer, HTR 58, ’65, 263–77 (Lucas); BGärtner, The Temple and the Community in Qumran and in the NT ’65; RClements, God and Temple ’65 (AT).</p><p class=\"entry-text\">ⓔ Os usos em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:19</a>, 20, 21 exigem atenção especial. Jesus, estando no templo de Jerusalém, exclama: <span class=\"greek\">λύσατε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">τοῦτον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τρισίν</span> <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">ἐγερῶ</span> <span class=\"greek\">αὐτόν</span>, destruí este templo, e em três dias o levantarei (versículo 19), o que algumas pessoas na narrativa entendem como referência ao edifício material (versículo 20), mas o narrador interpreta como referência ao <span class=\"greek\">ναὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">αὐτοῦ</span>, templo de seu corpo (versículo 21) (AMDubarle, Le signe du Temple [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:19</a>]: RB 48, ’39, 21–44; OCullmann, TZ 4, ’48, 367). Cf. a descrição do corpo de Cristo como <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">ν</span>. AcPlCor 2:17.—B. 1465. DELG. M-M. DLNT 1159–66. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναούμ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναούμ</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">נַחוּם</span>, cf. Na 1:1.—Em Jos., Ant. 9, 239 <span class=\"greek\">Ναοῦμος</span>), Naum, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:25</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναοφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ναοφόρος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ναός</span>, <span class=\"greek\">φέρω</span>; hápax), relativo a carregar a imagem de um templo ou santuário (ver <span class=\"greek\">ναός</span> a); substantivado, portador de templo ou de santuário, com outros compostos em -<span class=\"greek\">φόρος</span> IEph 9:2. Evidentemente, o autor tem em mente uma procissão religiosa politeísta.—DELG s.v. <span class=\"greek\">φέρω</span> D 2 p. 1190.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νάρδος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νάρδος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (provavelmente um empréstimo semítico [HLewy, Die sem. Fremdwörter im Griech. 1895, 40], mas, em última instância, de origem indo-europeia [persa nārdīn; sânscrito naladâ]).</p><p class=\"entry-text\">① Planta aromática da qual se obtém o óleo de nardo, nardo (En 32:1), erva perene da família das valerianáceas: Zohary 205, originária da Índia (Onesicritus: 134 Fgm. 22 Jac.; Arrian, Anab. 6, 22, 5) <span class=\"greek\">στέφανος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">νάρδου</span> <span class=\"greek\">στάχυος</span> <span class=\"greek\">πεπλεγμένος</span>, guirlanda tecida com flores de nardo ApcPt 3:10 (cf. Theophr., HP 9, 7, 2ff).</p><p class=\"entry-text\">② Óleo aromático da planta de nardo, extraído da raiz (Nicander, Ther. 937, Alexiph. 402 <span class=\"greek\">νάρδου</span> <span class=\"greek\">ῥίζαι</span>), óleo de nardo (ver Peripl. Eryth. c. 39; 48; Diosc., Mat. Med. 1, 6, 75; Pliny, NH 12, 26; 13, 2; 4; PSI 628, 7 [III a.C.]; PEdg 69 [=Sb 6775], 5 [257 a.C.]; POxy 1088, 49; PGM 13, 19; 353; SSol 1:12; 4:13f) <span class=\"greek\">μύρον</span> <span class=\"greek\">νάρδου</span>, unguento ou perfume de nardo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a>. Nesta última passagem, uma libra desse óleo é avaliada em 300 denários, o salário médio de um trabalhador por quase dez meses (versículos 3 e 5). ILöw, D. Flora d. Juden III 1924, 482–88; SNaber, <span class=\"greek\">Νάρδος</span> <span class=\"greek\">πιστική</span>: Mnemosyne 30, 1902, 1–15; WSchoff, Nard: JAOS 43, 1925, 216–28; JBrown, The Mediterranean Vocab. of the Vine, VetusT 19, ’69, 160–64; New Docs 1, 85.—DELG. M-M. Ver <span class=\"greek\">πιστικός</span> 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νάρκη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νάρκη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (em várias acepções Hippocr., Aristoph. e outros; TestSol 18:19; Philo), torpor, dormência, insensibilidade. Esta palavra é incorretamente restaurada como [ …. <span class=\"greek\">πολ</span>]|<span class=\"greek\">λῇ</span> <span class=\"greek\">λυθεῖσα</span> <span class=\"greek\">ν</span>[<span class=\"greek\">άρκῃ</span> em algumas edições de Ox 1081, 3 (CWessely, PatrOr 18, 1924, 494; Kleine Texte 83 p. 25 apêndice [Sweete], e Otero I 82), em lugar de <span class=\"greek\">ἐ</span>]<span class=\"greek\">ληλύθεισαν</span> [<span class=\"greek\">διαφο</span>]<span class=\"greek\">ρά</span>. Ver <span class=\"greek\">ἔρχομαι</span> 1a<span class=\"greek\">ζ</span>.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νάρκισσος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νάρκισσος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, Narciso, nome bastante frequente entre escravos e libertos (Tacitus, Ann. 13, 1; Sueton., Claudius 28; Cass. Dio 64, 3, 4; IMagnMai 122d, 14; IHierap 80; IG XII, 8, 548, 2; CIL VI 4123; 4346; 5206 e outros). Paulo saúda <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ναρκίσσου</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, aqueles da casa de Narciso que são cristãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:11</a> (referência a escravos de <span class=\"greek\">Ν</span>. Cf. Narcissiani CIL III 3973, VI 15640).—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναυαγέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ναυαγέω</span> (<span class=\"greek\">ναῦς</span>, <span class=\"greek\">ἄγνυμι</span>, “quebrar”); 1º aoristo <span class=\"greek\">ἐναυάγησα</span> (Aeschyl., Hdt. e posteriores; POxy 839, 6ff; Philo).</p><p class=\"entry-text\">① Passar pela destruição de um navio, sofrer naufrágio, arruinar-se: <span class=\"greek\">τρὶς</span> <span class=\"greek\">ἐναυάγησα</span>, sofri naufrágio três vezes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:25</a>. Sobre os perigos no mar: New Docs 3, 58f.</p><p class=\"entry-text\">② Experimentar grande perda ou calamidade, sofrer naufrágio figuradamente, extensão de 1 (Cebes 24, 2 <span class=\"greek\">ὡς</span> <span class=\"greek\">κακῶς</span> <span class=\"greek\">διατρίβουσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀθλίως</span> <span class=\"greek\">ζῶσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ναυαγοῦσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βίῳ</span>; Philo, Mut. Nom. 215, Somn. 2, 147) <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἐναυάγησαν</span>, sofreram naufrágio na fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:19</a>.—DELG s.v. <span class=\"greek\">ναυαγός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναυή, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναυή</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">נוּן</span>. Cf. Ex 33:11; Num 11:28; Josh 1:1 e outros. Em todas essas passagens, a LXX traduz <span class=\"hebrew\" dir=\"rtl\">נוּן</span> por <span class=\"greek\">Ναυή</span>; cf. Jos., Bell. 4, 459; Just., Mel.—1 Ch 7:27; <span class=\"greek\">Νούμ</span>; PKatz TZ 9, ’53, 230), Num, pai de Josué 1 Cl 12:2; 12:8f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναύκληρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ναύκληρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ναῦς</span>, <span class=\"greek\">κλῆρος</span>; Soph., Hdt. e posteriores; Plut., Jos. [ambos com <span class=\"greek\">κυβερνήτης</span>, ver este verbete 1]; OGI 344, 4 [I a.C.]; papiros [Preisigke, Fachwörter; para outros, New Docs, abaixo]; En 101:4, 9; Philo, Op. M. 147), frequentemente “proprietário de navio” ou “afretador” de uma embarcação. Mas também pode significar capitão, pois o responsável pela navegação de um navio a serviço do Estado (especialmente para transporte de cereais IG 14, 918) era chamado <span class=\"greek\">ναύκληρος</span> (MRostovtzeff, APF 5, 1913, 298; LCasson, Ships and Seamanship in the Ancient World, ’71, 314–16; mas WKunkel, APF 8, ’27, 185, “contratante do frete”, não necessariamente piloto ou capitão) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:11</a>. (Sobre regulamentos de navegação POxy 3250, 22–24 [63 d.C.], ver New Docs 2, 74 n.º 25.)—Nock, Essays 823; Hemer, Acts 138f; JVélissaropoulos, Les nauclères grecs, ’80; New Docs 4, 116f (papiros, inscrições e literatura).—DELG. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναῦς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ναῦς</span>, <span class=\"greek\">ἡ</span> (Hom. e posteriores; inscrições, papiros, LXX; Philo, Aet. M. 138 e outros; Jos., Vi. 165 e outros; SibOr 8, 348), acusativo <span class=\"greek\">ναῦν</span>, navio, somente de embarcações maiores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:41</a> (com <span class=\"greek\">ἐπικέλλω</span>, como em Od. 9, 148).—B. 727. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0242-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναύτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ναύτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ναῦς</span>; Hom. e outros; inscrições, papiros; Ezk 27:9 Aq.; 27:29 Sym.; Jos., Vi. 66, Ant. 9, 209; TestNapht 6:2; empréstimo no rabínico), marinheiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:27</a>, 30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:17</a>.—DELG s.v. <span class=\"greek\">ναῦς</span>. M-M.</p></section></article>"};
